def roman_numerals(s):
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        val = roman_map.get(s[i], 0)
        if val == 0:
            raise ValueError("Invalid character")
        if i + 1 < n:
            next_val = roman_map.get(s[i+1], 0)
            if val < next_val:
                total += next_val - val
                i += 2
                continue
        total += val
        i += 1
    return total
